CALAR(observations, ''$.observations.payee_account_PT10M_txn_value'') AS \\"payee_account_PT10M_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_account_d01_txn_value'') AS \\"payer_account_d01_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_account_allchannels_d01_txn_value'') AS \\"payer_account_allchannels_d01_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.same_payer_account_payee_d01_txn_count'') AS \\"same_payer_account_payee_d01_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payee_account_loadmoney_creditcard_p1d_txn_count'') AS \\"payee_account_loadmoney_creditcard_p1d_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payee_account_loadmoney_creditcard_p1d_txn_value'') AS \\"payee_account_loadmoney_creditcard_p1d_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.same_ifsc_neft_rtgs_payee_acc_unique_d01_count'') AS \\"same_ifsc_neft_rtgs_payee_acc_unique_d01_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_account_UPI_d01_txn_value'') AS \\"payer_account_UPI_d01_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payee_account_loadmoney_p1d_txn_count'') AS \\"payee_account_loadmoney_p1d_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payee_account_loadmoney_p1d_txn_value'') AS \\"payee_account_loadmoney_p1d_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payee_account_loadmoney_99_pt12h_txn_count'') AS \\"payee_account_loadmoney_99_pt12h_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_account_imps_p1d_txn_count'') AS \\"payer_account_imps_p1d_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_unique_payee_acc_d01_txn_count'') AS \\"payer_unique_payee_acc_d01_txn_count\\", JSON_EXTRACT_SCALAR(observations, ''$.observations.payer_account_imps_p1d_txn_value'') AS \\"payer_account_imps_p1d_txn_value\\", JSON_EXTRACT_SCALAR(observations, ''$.observat